    #include <bits/stdc++.h>
using namespace std;

// Case 1: Odd order magic square (Siamese method)
vector<vector<int>> fillOddMagicSquare(int n)
{
    vector<vector<int>> mat(n, vector<int>(n, 0));

    int i = n / 2;
    int j = n - 1;

    for (int num = 1; num <= n * n;)
    {
        if (i == -1 && j == n)
        {
            i = 0;
            j = n - 2;
        }
        else
        {
            if (j == n)
                j = 0;
            if (i == -1)
                i = n - 1;
        }

        if (mat[i][j] != 0)
        {
            i++;
            j -= 2;
            continue;
        }

        mat[i][j] = num++;

        i--;
        j++;
    }

    return mat;
}

// Case 2: Doubly even (n % 4 == 0)
vector<vector<int>> fillDoublyEvenMagicSquare(int n)
{
    vector<vector<int>> mat(n, vector<int>(n));

    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            mat[i][j] = i * n + j + 1;
        }
    }

    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            if (((i % 4 == 0 || i % 4 == 3) && (j % 4 == 1 || j % 4 == 2)) ||
                ((i % 4 == 1 || i % 4 == 2) && (j % 4 == 0 || j % 4 == 3)))
            {
                mat[i][j] = n * n + 1 - mat[i][j];
            }
        }
    }

    return mat;
}

// Case 3: Singly even (n = 4k + 2)
vector<vector<int>> fillSinglyEvenMagicSquare(int n)
{
    vector<vector<int>> mat(n, vector<int>(n));

    vector<vector<int>> half = fillOddMagicSquare(n / 2);

    int add = (n * n) / 4;
    int k = (n - 2) / 4;

    // A (top-left)
    for (int i = 0; i < n / 2; i++)
        for (int j = 0; j < n / 2; j++)
            mat[i][j] = half[i][j];

    // C (top-right)
    for (int i = 0; i < n / 2; i++)
        for (int j = n / 2; j < n; j++)
            mat[i][j] = half[i][j - n / 2] + 2 * add;

    // D (bottom-left)
    for (int i = n / 2; i < n; i++)
        for (int j = 0; j < n / 2; j++)
            mat[i][j] = half[i - n / 2][j] + 3 * add;

    // B (bottom-right)
    for (int i = n / 2; i < n; i++)
        for (int j = n / 2; j < n; j++)
            mat[i][j] = half[i - n / 2][j - n / 2] + add;

    return mat;
}

void fillMagicSquare(int n, vector<vector<int>> &mat)
{
    if (n % 2 == 1)
        mat = fillOddMagicSquare(n);
    else if (n % 4 == 0)
